UPDATE projects SET mode = 'portfolio', eyebrow = 'Medical imaging application', summary = 'A production application for Baylor Medical Center that correlated 2D biopsy scans with a 3D biopsy model and reconstructed outlined tumor tissue in context.', year = 'Production archive', status = 'Production application', scope = 'A production medical imaging application for aligning 2D biopsy scans with a three-dimensional biopsy model and reconstructing marked regions in context.', ownership_json = '["Worked with 3D and 2D biopsy scan inputs in the application workflow.","Mapped outlined regions across scan slices into a reconstructed 3D representation.","Built an explorable browser visualization to communicate the scan-to-model process."]', note = 'The interactive demo on this site uses synthetic geometry only. It is separate from the production application and is not a diagnostic tool or clinical advice.' WHERE id = 'tumor-identifier';
