INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, mode, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('stream-dj', 20, 'Stream DJ', 'AI broadcast studio', 'A local-first desktop studio exploring audience requests, AI DJ voice, show programming, and audio playback for livestreams and radio-style shows.', '', 'Creator · Engineer', 'Current', '["Electron","React","TypeScript","Vite"]', 'SDJ', 'ice', 'AI + Automation', 'lab', 'Active prototype', '["Explores a moderated queue for audience music requests.","Pairs DJ voice links with a local song library and on-air controls.","Keeps the studio local-first and provider-neutral."]', 'What would a local-first, AI-assisted broadcast desk look like for an independent streamer?', '["Built an Electron station workspace with on-air controls and a persistent player.","Explored DJ voice announcements, requests, and reusable programming blocks.","Separated music, text, and voice providers so the studio can evolve without one provider dependency."]', '["Electron desktop shell","React and TypeScript interface","Local backend and station data"]', 'The repository describes this as an early prototype; integrations and show automation are still evolving.', NULL, NULL, 1, 0, 1) ON CONFLICT(id) DO NOTHING;
--> statement-breakpoint
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, mode, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('jcal', 21, 'jcal', 'Home calendar assistant', 'A touch-first home calendar workspace exploring shared family schedules, lists, weather, and natural-language commands.', '', 'Creator · Engineer', 'Current', '["Electron","React","TypeScript","Gemini"]', 'JCL', 'amber', 'AI + Automation', 'lab', 'In development', '["Brings multiple calendars into a wall-display interface.","Explores shared lists and color-coded family profiles.","Uses natural-language commands for household planning."]', 'How can a shared household display make schedules and everyday lists easier to use?', '["Built an Electron and React application for touch screens and kiosk use.","Explored calendar aggregation, family profiles, and shared lists.","Connected natural-language commands through a Gemini integration."]', '["Electron and React","Calendar integrations","Gemini-powered commands"]', 'The project is a work in progress; this record describes the repository''s current direction.', NULL, NULL, 1, 0, 1) ON CONFLICT(id) DO NOTHING;
--> statement-breakpoint
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, mode, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('markdown-podcast-narrator', 23, 'Markdown Podcast Narrator', 'Notes into spoken episodes', 'A desktop experiment that turns Markdown and research notes into editable two-host conversations, then renders distinct local voices into an MP3.', '', 'Creator · Engineer', 'Current', '["Electron","Node.js","Kokoro","FFmpeg"]', 'POD', 'ice', 'Creative Tools', 'lab', 'Open-source release', '["Drafts an editable two-host conversation from source notes.","Renders distinct Kokoro voices locally and saves an MP3.","Also supports a single-narrator reading mode without an AI writer."]', 'Can written notes become a useful spoken explanation while keeping the script editable?', '["Built the Electron episode studio and source intake workflow.","Connected optional writing providers for conversation drafts.","Added local Kokoro voice rendering, MP3 output, and playback."]', '["Electron desktop app","Optional local or CLI writing providers","Kokoro voice synthesis and FFmpeg"]', 'The writing provider is optional; voice generation runs locally after its model is available.', 'View source and releases', 'https://github.com/nascarjake/markdown-podcast-narrator', 1, 0, 1) ON CONFLICT(id) DO NOTHING;
--> statement-breakpoint
INSERT INTO projects (id, sort_order, title, eyebrow, summary, story_html, role, year, stack_json, signal, accent, category, mode, status, highlights_json, scope, ownership_json, systems_json, note, source_label, source_url, published, featured, version) VALUES ('music-writer', 24, 'Music Writer', 'Audio-to-code music research', 'A music analysis workspace exploring how separated audio stems and note events can become a reproducible Strudel arrangement.', '', 'Creator · Researcher', 'Current', '["Python","HTDemucs","Basic Pitch","Strudel"]', 'MUW', 'acid', 'Creative Tools', 'lab', 'Research workspace', '["Separates a recording into instrumental stems for analysis.","Fits detected notes and drum transients to a rhythmic grid.","Generates Strudel reconstructions from the resulting events."]', 'How much of a recorded arrangement can be reconstructed as editable music code?', '["Created an analysis pipeline for stem separation and note extraction.","Mapped detected events to a beat grid and section structure.","Produced Strudel versions of the analyzed arrangement."]', '["Python analysis scripts","HTDemucs and Basic Pitch","Strudel music code"]', 'The current workspace documents one transcription study; this is research material rather than a released app.', NULL, NULL, 1, 0, 1) ON CONFLICT(id) DO NOTHING;
